WITH lines AS (SELECT id, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS tier_value), with_windows AS (SELECT *, DENSE_RANK() OVER w_ordered AS tier_value_dense_rank, DENSE_RANK() OVER w_ordered AS tier_value_dense_rank_2 FROM lines WINDOW w_ordered AS (PARTITION BY currency ORDER BY tier_value DESC NULLS LAST)), valid AS (SELECT currency, tier_value_dense_rank_2, ROUND(tier_value_dense_rank / tier_value_dense_rank_2, 2) AS tier_value_dense_rank_per_tier_value_dense_rank_2 FROM with_windows WHERE currency IN ('USD', 'THB', 'EUR')), base AS (SELECT *, INITCAP(TRIM(currency)) AS currency_title FROM valid WHERE currency IN ('THB', 'USD')), with_windows_price_tiers AS (SELECT currency, tier_value_dense_rank_2, tier_value_dense_rank_per_tier_value_dense_rank_2, ROUND(tier_value_dense_rank_2 / SUM(tier_value_dense_rank_2) OVER (PARTITION BY currency), 4) AS tier_value_dense_rank_2_share, ROUND(tier_value_dense_rank_2 / SUM(tier_value_dense_rank_2) OVER (PARTITION BY currency), 4) AS tier_value_dense_rank_2_share_2 FROM base) SELECT currency, tier_value_dense_rank_2, tier_value_dense_rank_per_tier_value_dense_rank_2 FROM with_windows_price_tiers;
